<template><main class="resources-view"><header><div><p>我的资源库</p><h1>药柜藏卷</h1></div><input v-model="query" placeholder="搜索标题或知识点" @input="load"/></header><section class="filters"><button v-for="item in types" :key="item.value || 'all'" :class="{ active: resourceType === item.value }" @click="chooseType(item.value)">{{ item.label }}</button><label><input v-model="favorited" type="checkbox" @change="load"/> 仅收藏</label></section><section v-if="resources.loading" class="state"><StateLoading size="md"/></section><section v-else-if="resources.items.length" class="grid"><ResourceCard v-for="(item,index) in resources.items" :key="item.id" :resource="item" :style="{ '--card-index': index }" @favorite="resources.toggleFavorite(item.id)" @open="open"/></section><section v-else class="state"><StateEmpty title="柜中还没有药签" description="去脉络图开一炉，把第一份资源收入卷册。" action-text="前往脉络图" @action="router.push('/meridian-map')"/></section></main></template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import ResourceCard from '../components/resources/ResourceCard.vue'
import { StateEmpty, StateLoading } from '../components/state'
import { useResourcesStore } from '../stores/resources'
import type { ResourceType } from '../types/resource'
const resources = useResourcesStore(); const router = useRouter(); const query = ref(''); const resourceType = ref<ResourceType | undefined>(); const favorited = ref(false)
const types: Array<{ label: string; value: ResourceType | undefined }> = [{ label: '全部', value: undefined }, { label: '书卷', value: 'doc' }, { label: '图谱', value: 'graph' }, { label: '导图', value: 'mindmap' }, { label: '签筒', value: 'quiz' }, { label: '戏台', value: 'story' }]
const load = () => void resources.load({ q: query.value || undefined, type: resourceType.value, favorited: favorited.value || undefined })
const chooseType = (value: ResourceType | undefined) => { resourceType.value = value; load() }
const open = (item: { id: string }) => void router.push({ name: 'resource-detail', params: { id: item.id } })
onMounted(load)
</script>
<style scoped lang="scss">.resources-view{width:min(1280px,100%);margin:auto}.resources-view header{display:flex;justify-content:space-between;gap:var(--qh-space-6);align-items:end;margin:var(--qh-space-2) 0 var(--qh-space-5)}.resources-view header p{margin:0 0 6px;color:var(--qh-color-jade);font-size:12px;letter-spacing:1.5px}.resources-view h1{margin:0;font-family:var(--qh-font-display);font-size:31px}.resources-view header input{width:280px;padding:10px 12px;border:1px solid var(--qh-border);border-radius:var(--qh-radius-stage);color:var(--qh-text);background:color-mix(in srgb,var(--qh-color-night-soft) 60%,transparent)}.filters{display:flex;flex-wrap:wrap;gap:var(--qh-space-2);padding-bottom:var(--qh-space-5);border-bottom:1px solid var(--qh-border)}.filters button{padding:7px 12px;border:1px solid var(--qh-border);border-radius:var(--qh-radius-pill);color:var(--qh-text-muted);background:transparent;cursor:pointer}.filters button.active{border-color:var(--qh-color-jade);color:var(--qh-color-ink);background:var(--qh-color-jade)}.filters label{padding:7px 5px;color:var(--qh-text-muted);font-size:13px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(255px,1fr));gap:var(--qh-space-3);margin-top:var(--qh-space-5)}.grid :deep(.resource-card){animation:card-in .32s calc(var(--card-index) * 70ms) both ease-out}.state{display:grid;min-height:400px;place-items:center}@keyframes card-in{from{opacity:0;transform:translateY(10px)}}@media(max-width:600px){.resources-view header{align-items:start;flex-direction:column}.resources-view header input{width:100%}}@media(prefers-reduced-motion:reduce){.grid :deep(.resource-card){animation:none}}</style>
